import torch
import torch.nn as nn
import torch.nn.functional as F
class Sq(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        return x ** 2
    @staticmethod
    def backward(ctx, g):
        x, = ctx.saved_tensors
        return 2 * x * g
x = torch.tensor(3., requires_grad=True)
y = Sq.apply(x)
y.backward()
print(repr((y, x.grad)))
